-- MP-0039: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='amanah' and type='party') then raise exception 'MP-0039: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0039: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='wawasan' and type='party') then raise exception 'MP-0039: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mas-ermieyati-samsudin','adly-zahari','bakri-jamaluddin') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0039: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('masjid tanah','alor gajah','tangga batu') and slug not in ('mas-ermieyati-samsudin','adly-zahari','bakri-jamaluddin')) then raise exception 'MP-0039: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0039:%' and (m.source_type <> 'editorial' or e.slug not in ('mas-ermieyati-samsudin','adly-zahari','bakri-jamaluddin') or m.import_key not like 'MP-0039:' || e.slug || ':%')) then raise exception 'MP-0039: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mas-ermieyati-samsudin','Mas Ermieyati Samsudin','opposition','Chair of the Public Accounts Committee; Member of the Dewan Rakyat','Masjid Tanah','Melaka','Mas Ermieyati Samsudin represents Masjid Tanah, Melaka, in the Dewan Rakyat. Current role: Chair of the Public Accounts Committee; Member of the Dewan Rakyat. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4173','/portraits/mas-ermieyati-samsudin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P134.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4173"}, {"label": "Wawasan · women’s chief, 23 October 2026", "url": "https://www.freemalaysiatoday.com/category/bahasa/tempatan/2026/10/23/politik-identiti-mungkin-pengaruhi-anak-muda-melaka"}, {"label": "Parliament · PAC chair’s October 2026 statements", "url": "https://www.parlimen.gov.my/pac/kenyataan_media_2026.html"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'adly-zahari','Adly Zahari','government','Deputy Minister of Defence','Alor Gajah','Melaka','Adly Zahari represents Alor Gajah, Melaka, in the Dewan Rakyat. Current role: Deputy Minister of Defence. A AMANAH member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4174','/portraits/adly-zahari.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P135.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4174"}, {"label": "AMANAH · vice-president, 2 August 2026", "url": "https://www.bernama.com/en/politics/news.php?id=2589309"}]'::jsonb from public.entities parent where parent.slug='amanah' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'bakri-jamaluddin','Bakri Jamaluddin','opposition','Member of the Dewan Rakyat','Tangga Batu','Melaka','Bakri Jamaluddin represents Tangga Batu, Melaka, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4175','/portraits/bakri-jamaluddin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P136.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4175"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mas-ermieyati-samsudin','adly-zahari','bakri-jamaluddin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0039: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0039:adly-zahari:2026-veteran-housing','Build 40 new veteran homes and repair 280 homes in the 2026 programme','Housing',null,null,'2026-12-31','2026-01-15','https://www.bernama.com/bm/am/news.php?id=2512901',null,null,'Adly announced JHEV’s RM8 million programme, with quotations followed by hoped-for construction and repairs from March or April.','The primary report is dated 15 January. Prior-year approvals are not 2026 completions. The 2026 programme uses a year-end target marker; a complete comparable delivery total was not verified.','2026-11-09','editorial',false from public.entities e where e.slug='adly-zahari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0039:adly-zahari:jasin-veteran-key-handover','Hand over a new home under the veterans’ housing initiative in Jasin','Housing','achieved',null,null,null,null,'2025-12-15','https://www.mod.gov.my/index.php/media2/berita/timbalan-menteri-pertahanan-sempurnakan-majlis-penyerahan-kunci-rumah-bina-baharu-di-bawah-program-inisiatif-perumahan-veteran-angkatan-tentera-malaysia-atm','The Defence Ministry records Adly officiating the handover of a newly built home under the Armed Forces veterans’ housing initiative.','A dated 2025 handover, not proof of the separate 2026 national 40-new-home target. Delivery is shared with JHEV and the implementing agencies.','2026-11-09','editorial',false from public.entities e where e.slug='adly-zahari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

